import json
from pathlib import Path
from datetime import datetime,timezone
HERE=Path(__file__).resolve().parent
base=json.loads((HERE/'exhaust-remove-refit-v1.procedure.json').read_text())
url=base['source']['source_url']
p={k:base[k] for k in ['schema_version','target','scope_confirmed','status','publication_status']}
p.update(id='yamaha-2026-yz450f-coolant-change-v1',title='Change the coolant',completeness='Complete stock assembled cooling-system drain, flush, refill, cap installation, warm/cool cycle and cold-level recheck. Hoses, radiators and pump remain assembled.',source={**base['source'],'pdf_pages':[106,107],'printed_pages':['3-22','3-23'],'review_note':'Both pages rendered and visually reviewed. Original mechanical instructions only; source emergency-treatment text is not reproduced.'},applicability={'included':'Stock US 2026 YZ450F assembled cooling system','excluded':['Other years/models','Aftermarket cooling-system volume','Hose/radiator/pump repair','Pressure testing','Engine restart while another repair remains incomplete'],'year_inheritance':'NONE'},required_tools=[{'name':'Stable upright bike support on level ground'},{'name':'Coolant collection container and thick cloth'},{'name':'Drain-bolt tool and torque wrench accurate at10 N·m'},{'name':'Clean measuring/mixing container and funnel'}],required_parts=[{'name':'New coolant-drain copper washer','source_pdf_page':107},{'name':'High-quality ethylene-glycol antifreeze with corrosion protection for aluminum engines','source_pdf_page':107},{'name':'Distilled water for the final1:1 coolant/water mix; soft water only if distilled unavailable','source_pdf_page':107},{'name':'Clean tap water for flushing','source_pdf_page':107}],preflight=['Engine stopped and completely cool; do not open a hot pressurized radiator.','Cooling system assembled and free of known damage; final engine start only after every concurrent repair is closed.','Compatible coolant type identified; do not mix antifreeze types.'],critical_stop_conditions=['Radiator/engine still hot or pressure release not complete.','Leak, damaged washer seat or cap cannot secure.','Another engine repair remains incomplete: do not perform warm-up.','Final concentration or cold level unresolved.'],fluid_spec={'nominal_complete_system_l':1.03,'mix_coolant_to_water':'1:1','basis':'Total radiator including all routes; not an instruction to overfill beyond source maximum-level diagram.','final_check':'Confirm correct mixture; adding water or residual flushing water can reduce antifreeze concentration. A ready1:1 mixture is not concentrate to dilute again.'},steps=[])
rows=[
('prepare','Set up for a cold drain','Stand the cooled bike upright on a level surface. Place the collection container beneath the engine and position it close to the drain outlet, because flow can shoot sideways when the radiator cap is released.',[106,107],'Bike stable; engine and coolant cold; collection ready.',False),
('drain','Open the drain and radiator cap','Remove the coolant drain bolt and its copper washer. Place a thick cloth over the radiator cap and turn it slowly counterclockwise toward its detent to release residual pressure. Once hissing stops, press down and turn farther to remove the cap. Let the coolant drain into the container.',[107],'Drain complete; old washer removed; cap opened only when cold.',False),
('flush','Flush the system','Flush the cooling system thoroughly with clean tap water as Yamaha specifies, collecting the discharge. Let flushing water drain before installing the drain bolt; retained water affects the final antifreeze concentration.',[107],'Flush complete; discharge collected and drained.',False),
('seal','Install a new drain washer','Install a new copper washer and the coolant drain bolt. Tighten the bolt to10 N·m.',[107],'New washer installed; drain bolt10 N·m.',True),
('fill','Refill with the specified mixture','Use the specified aluminum-compatible ethylene-glycol antifreeze and distilled water at a final1:1 coolant-to-water ratio. Do not mix antifreeze types. Fill to the maximum level illustrated in PDF106. The complete system nominal volume is1.03 L including all routes; correct level and concentration govern, not forcing in that amount after an incomplete drain. Wash any spill on paint away immediately with water.',[106,107],'Mixture/product and amount recorded; level at illustrated maximum.',True),
('cap','Secure the radiator cap','Install and secure the radiator cap. Account for the drain hardware, collection container and tools before running the engine.',[107],'Cap secured; drain sealed; tools clear.',False),
('warm-cool','Run the prescribed settling cycle','Only with the cooling system and all other work fully assembled, start the engine and warm it for several minutes. Stop it and allow it to cool completely before opening the cap again.',[107],'Warm-up completed and engine subsequently fully cooled.',True),
('recheck','Recheck the cold level','Keep the bike upright on level ground. With the engine cooled, use the cloth and slow pressure-release method to remove the cap. Allow the coolant to settle, check against the illustrated maximum and add the correct mixture if low. Restore the cap securely. A leak or repeatedly dropping level requires repair rather than repeated top-offs.',[106,107],'Final cold level and mixture recorded; cap secured; no unresolved loss.',True),
('complete','Save the coolant service','Record coolant type, final mix, amount added, new washer, drain torque, warm/cool cycle and final cold level. Clean up collected fluids and check for leaks. Mark only this coolant change complete; it does not verify a separately opened engine or cooling component.',[106,107],'All recorded checks pass; any fault retained.',True)]
for i,(id,title,instruction,pages,verification,record) in enumerate(rows):
    p['steps'].append({'id':id,'title':title,'instruction':instruction,'depends_on':[] if i==0 else [rows[i-1][0]],'source_pdf_pages':pages,'verification':[verification],'diagram_reference_required':True,'source_links':[url+'#page='+str(n) for n in pages],'record_required':record,'origin':'Original source-based mechanical summary; collection, logging and concurrent-work checks are workflow adaptations.'})
p['reviewed_at']=datetime.now(timezone.utc).isoformat()
(HERE/'coolant-change-v1.procedure.json').write_text(json.dumps(p,indent=2)+'\n',encoding='utf-8')
print('Saved complete9-step stock coolant change.')
